const topics = [
  { query: 'site:huggingface.co trending models', category: 'ai_models' },
  { query: 'free text to video AI 2026', category: 'video_gen' },
  { query: 'local LLM optimization techniques', category: 'ai_physics' },
  { query: 'free image generation API no signup', category: 'image_gen' },
  { query: 'Web Speech API advanced features', category: 'voice' },
  { query: 'n8n workflow optimization patterns', category: 'automation' },
  { query: 'avatar animation three.js lip sync', category: 'avatar' },
  { query: 'capacity intelligence enterprise software', category: 'market' }
];
const today = new Date().getDay();
const topic = topics[today % topics.length];
return [{ json: topic }];

const html = $input.first().json.data || '';
// Extract result snippets (basic extraction from DDG HTML)
const snippets = html.match(/class="result__snippet">(.*?)<\/a>/g) || [];
const findings = snippets.slice(0, 5).map(s => s.replace(/<[^>]*>/g, '').trim());
return [{ json: {
  category: $('Research Topics').item.json.category,
  query: $('Research Topics').item.json.query,
  findings: findings.join(' | ') || 'No results extracted',
  ts: new Date().toISOString()
} }];

const fs = require('fs');
const entry = JSON.stringify({
  ts: $json.ts,
  topic: $json.query,
  finding: $json.findings,
  source: 'duckduckgo',
  category: $json.category,
  actionable: true
});
fs.appendFileSync('/home/user/Orbital/nova/memory/research.jsonl', entry + '\n');
return [{ json: { logged: true } }];
